SELECT balance_minor FROM accounts WHERE account_id = 109;
-- A: the payment writes 5000 - 1000
UPDATE accounts SET balance_minor = 4000 WHERE account_id = 109;
-- B: the fee writes 5000 - 1000 too (this one waits)
UPDATE accounts SET balance_minor = 4000 WHERE account_id = 109;
-- A
COMMIT;
-- B
COMMIT;
-- A
SELECT balance_minor FROM accounts WHERE account_id = 109;
