-- the atomic version: A, then B, then A's COMMIT, then B's COMMIT
BEGIN;                                                                      -- A
UPDATE accounts SET balance_minor = balance_minor - 1000 WHERE account_id = 109;  -- A
BEGIN;                                                                      -- B
UPDATE accounts SET balance_minor = balance_minor - 1000 WHERE account_id = 109;  -- B (waits)
COMMIT;                                                                     -- A
COMMIT;                                                                     -- B
SELECT balance_minor FROM accounts WHERE account_id = 109;                  -- A
UPDATE accounts SET balance_minor = 5000 WHERE account_id = 109;           -- A: put it back

-- A, at Read Committed (the default)
BEGIN;
SELECT balance_minor FROM accounts WHERE account_id = 109;
-- B
UPDATE accounts SET balance_minor = balance_minor - 1000 WHERE account_id = 109;
-- A
SELECT balance_minor FROM accounts WHERE account_id = 109;
COMMIT;

