-- A
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance_minor) FROM accounts WHERE customer_id = 9;
-- B
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance_minor) FROM accounts WHERE customer_id = 9;
-- A: 10000 >= 8000, so withdraw from 109
UPDATE accounts SET balance_minor = balance_minor - 8000 WHERE account_id = 109;
-- B: 10000 >= 8000, so withdraw from 209
UPDATE accounts SET balance_minor = balance_minor - 8000 WHERE account_id = 209;
-- A
COMMIT;
-- B
COMMIT;
-- A
