-- A
BEGIN;
SELECT account_id, balance_minor FROM accounts WHERE customer_id = 9 ORDER BY account_id FOR UPDATE;
-- B (waits)
BEGIN;
SELECT account_id, balance_minor FROM accounts WHERE customer_id = 9 ORDER BY account_id FOR UPDATE;
-- A
UPDATE accounts SET balance_minor = balance_minor - 8000 WHERE account_id = 109;
COMMIT;
-- B
SELECT sum(balance_minor) FROM accounts WHERE customer_id = 9;
ROLLBACK;
-- A
UPDATE accounts SET balance_minor = 5000 WHERE customer_id = 9;

