-- 2. one refund of a payment at a time: lock the parent row first
BEGIN;
SELECT amount_minor FROM payments WHERE payment_id = 5 FOR UPDATE;   -- the second agent waits here
SELECT coalesce(sum(amount_minor), 0) FROM refunds WHERE payment_id = 5;
-- a new statement, so a new snapshot: the second agent sees 43000, refundable 5000
-- insert only if 48000 - sum >= 25000
COMMIT;

// 3. the service method
fun refund(conn: Connection, paymentId: Long, amount: Long): Boolean {
    conn.autoCommit = false
    try {
        val paid = conn.prepareStatement("SELECT amount_minor FROM payments WHERE payment_id = ? FOR UPDATE")
            .use { it.setLong(1, paymentId); it.executeQuery().use { rs -> rs.next(); rs.getLong(1) } }
        val refunded = conn.prepareStatement("SELECT coalesce(sum(amount_minor), 0) FROM refunds WHERE payment_id = ?")
            .use { it.setLong(1, paymentId); it.executeQuery().use { rs -> rs.next(); rs.getLong(1) } }
        if (refunded + amount > paid) {            // the rule, checked while we hold the lock
            conn.rollback()
            return false
        }
        conn.prepareStatement(
            "INSERT INTO refunds (payment_id, amount_minor, reason, created_at) VALUES (?, ?, 'customer_request', now())",
        ).use { it.setLong(1, paymentId); it.setLong(2, amount); it.executeUpdate() }
        conn.commit()                               // releases the lock: the next refund may check
        return true
    } catch (e: SQLException) {
        conn.rollback()
        throw e
    }
}

// 4. the same rule without FOR UPDATE: SERIALIZABLE plus a retry of everything
val ok = serializable(conn) { _ ->
    val paid = amountOf(conn, paymentId)               // plain SELECTs, no lock
    val refunded = refundedSoFar(conn, paymentId)
    if (refunded + amount > paid) false
    else { insertRefund(conn, paymentId, amount); true }
}
// the second agent's attempt fails with 40001; its retry sees 43000 and returns false
